/**
 * Generates supabase/seed.sql from @nexuse/catalog so DB seed data and app config cannot drift.
 * Usage: pnpm gen:seed            (writes the file)
 *        pnpm gen:seed --check    (exits 1 if the committed file is stale; used in CI)
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { COMMUNITIES, CATEGORIES_ALL } from '../packages/catalog/src/index';

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const lines: string[] = [
  '-- GENERATED by scripts/generate-seed.ts from @nexuse/catalog. Do not edit by hand.',
  '-- Idempotent: safe to run repeatedly. Never overwrites an admin\'s later community status changes.',
  '',
  'insert into public.communities (id, name, tagline, status, sort_order) values',
  COMMUNITIES.map((c) => `  (${q(c.id)}, ${q(c.name)}, ${q(c.tagline)}, ${q(c.status)}, ${c.sortOrder})`).join(',\n'),
  'on conflict (id) do update set name = excluded.name, tagline = excluded.tagline, sort_order = excluded.sort_order;',
  '',
];
for (const parentPass of [true, false]) {
  for (const c of CATEGORIES_ALL.filter((x) => !x.parentSlug === parentPass)) {
    const parent = c.parentSlug ? `(select id from public.categories where community_id = ${q(c.communityId)} and slug = ${q(c.parentSlug)})` : 'null';
    lines.push(`insert into public.categories (community_id, parent_id, slug, name, blurb, emoji, sort_order) values (${q(c.communityId)}, ${parent}, ${q(c.slug)}, ${q(c.name)}, ${q(c.blurb)}, ${q(c.emoji)}, ${c.sortOrder})`,
      '  on conflict (community_id, slug) do update set name = excluded.name, blurb = excluded.blurb, emoji = excluded.emoji, sort_order = excluded.sort_order, parent_id = excluded.parent_id;');
  }
}
const out = lines.join('\n') + '\n';
const file = new URL('../supabase/seed.sql', import.meta.url).pathname;
if (process.argv.includes('--check')) {
  if (!existsSync(file) || readFileSync(file, 'utf8') !== out) { console.error('supabase/seed.sql is stale: run `pnpm gen:seed`'); process.exit(1); }
  console.log('seed.sql is up to date');
} else { writeFileSync(file, out); console.log(`wrote ${file}`); }
